import numpy as np

def load(fid):
    rows = list(csv.DictReader(open(f"factors/{fid}_signal.csv")))
    d = {}
    for r in rows:
        d.setdefault(r["date"], {})[r["symbol"]] = float(r["value"])
    return d

fids = ["dn_mkt_beta_60d", "eurusd_beta_60d", "rate_beta_cn10y_60d"]
panels = {f: load(f) for f in fids}
common_dates = sorted(set.intersection(*[set(panels[f].keys()) for f in fids]))
print(f"common dates: {len(common_dates)}")

for a, b in combinations(fids, 2):
    rhos = []
    for dt in common_dates:
        ka, kb = panels[a][dt], panels[b][dt]
        syms = [s for s in ka if s in kb]
        x = [ka[s] for s in syms]; y = [kb[s] for s in syms]
        if len(x) >= 8:
            r = np.corrcoef(x, y)[0, 1]
            if not np.isnan(r): rhos.append(r)
