import json, base64, zlib, io, csv
import numpy as np
from itertools import combinations

fids = ["dn_mkt_beta_60d","eurusd_beta_60d","mom_10d_skip5","mom_120d_skip5",
        "rate_beta_cn10y_60d","vix_beta_cond_60x20","vol_of_vol20x60"]

def load_panel(fid):
    rec = json.load(open(f"factors/{fid}.json"))
    art = rec["validation"]["signal_artifact"]
    fmt = art.get("format")
    if fmt == "panel_json_v1":
        dates, assets, values = art["dates"], art["assets"], art["values"]
        return {d: {a: values[a][i] for a in assets} for i, d in enumerate(dates)}
    if fmt == "base64:zlib:csv":
        raw = zlib.decompress(base64.b64decode(art["data"])).decode()
        rows = list(csv.DictReader(io.StringIO(raw)))
        panel = {}
        for r in rows:
            panel[r["date"]] = {a: (float(r[a]) if r.get(a) not in (None, "", "nan") else None) for a in art["columns"]}
        return panel
    raise ValueError(f"unknown fmt {fmt}")

panels = {fid: load_panel(fid) for fid in fids}
print("loaded panels:", {fid: len(p) for fid, p in panels.items()})

print("\n=== Pairwise cross-sectional rank corr (common dates, >=8 assets) ===")
for a, b in combinations(fids, 2):
    common = sorted(set(panels[a]) & set(panels[b]))
    rhos = []
    for d in common:
        pa, pb = panels[a][d], panels[b][d]
        xs = [(pa[s], pb[s]) for s in pa if s in pb and pa[s] is not None and pb[s] is not None]
        if len(xs) >= 8:
            x = [p[0] for p in xs]; y = [p[1] for p in xs]
            r = np.corrcoef(x, y)[0, 1]
            if not np.isnan(r): rhos.append(r)
    if rhos:
        print(f"  {a:24s} vs {b:24s}: mean rho={np.mean(rhos):+.3f} (n={len(rhos)})")
EOF

