}
qs = {fid: abs(m["ic"]) * abs(m["icir"]) for fid, m in factors.items()}
total = sum(qs.values())
ensemble = {
    "schema_version": 1,
    "selected_factors": [
        {"factor_id": fid, "weight": round(q / total, 3), "direction": 1 if factors[fid]["ic"] > 0 else -1}
        for fid, q in sorted(qs.items(), key=lambda kv: -kv[1])
