import json, glob, os, numpy as np, pandas as pd

def load_signal(fid):
    jf = f'factors/{fid}.json'
    d = json.load(open(jf))
    sa = d['validation'].get('signal_artifact', {})
    # try direct signal table in artifact
    for key in ['signal_table','panel','signals','signal_csv']:
        if key in sa:
            v = sa[key]
            if isinstance(v, dict) and 'data' in v:
                return pd.DataFrame(v['data'])
            if isinstance(v, list):
                return pd.DataFrame(v)
    # encoded csv
    if 'signal_csv' in sa or 'csv' in sa:
        enc = sa.get('signal_csv') or sa.get('csv')
        if isinstance(enc, dict):
            enc = enc.get('data') or enc.get('encoded') or enc
        if isinstance(enc, str):
            import base64, zlib
            raw = base64.b64decode(enc)
            try:
                raw = zlib.decompress(raw)
            except Exception:
                pass
            return pd.read_csv(pd.io.common.BytesIO(raw))
    return None

# Inspect one artifact first
d = json.load(open('factors/dn_mkt_beta_60d.json'))
sa = d['validation']['signal_artifact']
print("artifact keys:", list(sa.keys()))
for k,v in sa.items():
    if isinstance(v, dict):
        print(k, "->", {kk: (f'<len {len(vv)}>' if isinstance(vv,(list,dict)) else vv) for kk,vv in list(v.items())[:6]})
    elif isinstance(v, str):
        print(k, "-> str len", len(v), v[:60])
    else:
        print(k, "->", type(v).__name__, v if not isinstance(v,(list,dict)) else f'len {len(v)}')
